document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("date-diff-form"),t=document.getElementById("date-diff-result");e.addEventListener("submit",function(e){e.preventDefault();const n=new Date(document.getElementById("start-date").value),a=new Date(document.getElementById("end-date").value);if(isNaN(n)||isNaN(a))return t.textContent="Please enter valid dates.",void 0;let d=a-n;const l=d<0;d=Math.abs(d);const o=Math.floor(d/864e5),i=n.getFullYear(),s=n.getMonth(),r=n.getDate(),u=a.getFullYear(),b=a.getMonth(),c=a.getDate();let f=Math.abs(u-i),m=Math.abs(b-s),g=Math.abs(c-r);if(c<r){m-=1;g=new Date(u,b,0).getDate()-r+c}b<s&&(f-=1,m=12-s+b);const h=1===o?"day":"days",y=1===f?"year":"years",D=1===m?"month":"months",M=1===g?"day":"days";t.innerHTML=`\n      <b>Date difference:</b><br>\n      <ul>\n        <li>Total days: <b>${o} ${h}</b></li>\n        <li>Breakdown: <b>${f} ${y}, ${m} ${D}, ${g} ${M}</b></li>\n        <li>Direction: <b>${l?"in the past":"in the future"}</b></li>\n      </ul>\n    `})});